const POLYS=NETD.poly,polyC=k=>{const q=POLYS[k];if(!q)return null;let A=0,cx=0,cz=0;for(let i=0;i<q.length;i++){const a=q[i],b=q[(i+1)%q.length],c=a[0]*b[1]-b[0]*a[1];A+=c;cx+=(a[0]+b[0])*c;cz+=(a[1]+b[1])*c}A/=2;return[cx/(6*A),cz/(6*A),Math.abs(A)]};
const inPoly=(k,x,z,m)=>{const q=POLYS[k];if(!q)return false;let ins=false;for(let i=0,j=q.length-1;i<q.length;j=i++){const a=q[i],b=q[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])ins=!ins}if(ins||!m)return ins;for(let i=0;i<q.length;i++){const a=q[i],b=q[(i+1)%q.length],dx=b[0]-a[0],dz=b[1]-a[1],t=cl(((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz||1),0,1);if(Math.hypot(x-a[0]-dx*t,z-a[1]-dz*t)<m)return true}return false};
